INSERT INTO oshi_skills (oshi_card_id, skill_type, skill_name, description, holopower_cost, effect_json) VALUES ('HSD01-001', 'NORMAL', 'リプレイスメント', '[ターンに１回]自分のステージのエール１枚を、自分のホロメンに付け替える。', 1, '{"type": "UNIMPLEMENTED", "rawText": "[ターンに１回]自分のステージのエール１枚を、自分のホロメンに付け替える。"}'::jsonb);
INSERT INTO oshi_skills (oshi_card_id, skill_type, skill_name, description, holopower_cost, effect_json) VALUES ('HSD01-001', 'SP', 'じゃあ敵だね？', '[ゲームに１回]相手のセンターホロメンとバックホロメン１人を交代させる。その後、このターンの間、自分の白センターホロメンのアーツ+50。', 2, '{"type": "UNIMPLEMENTED", "rawText": "[ゲームに１回]相手のセンターホロメンとバックホロメン１人を交代させる。その後、このターンの間、自分の白センターホロメンのアーツ+50。"}'::jsonb);
